	phoneVerified: boolean,
	/**  ISO date (`2000-01-02`). */
	birthdate: string | null,
	/**  None until known. */
	premium: boolean | null,
	/**  Premium tier name, e.g. `Premium 1000`; None without a subscription. */
	premiumPlan: string | null,
	/**  ISO date the subscription renews on. */
